/**
 * Owns the pure order-prince event payload shapes and inert-data readers used by
 * backend recording/projection and browser replay. Inputs are an event type and
 * JSON.parse data without revivers, or values already proven inert; outputs are
 * detached facts or null with the original field, nullable and ID boundaries.
 * This module never authorizes actions, settles effects, or writes role state.
 * Reflection may trigger Proxy traps; Node ingress owns hostile-object rejection.
 */
import { copyEventData } from "../inert-event-data";
export interface OrderPrinceRevoteFact {
  actorId: number;
}
export function readOrderPrinceRevoteFact(
  type: string,
  payload: unknown,
): OrderPrinceRevoteFact | null {
  if (type !== "order_prince_revote_started") return null;
  try {
    const p = copyEventData(payload);
    if (!p || typeof p !== "object" || Array.isArray(p)) return null;
    const row = p as Record<string, unknown>;
    return Object.keys(row).length === 1 &&
      Object.hasOwn(row, "actorId") &&
      typeof row.actorId === "number" &&
      Number.isSafeInteger(row.actorId) &&
      row.actorId > 0 &&
      row.actorId < Number.MAX_SAFE_INTEGER
      ? { actorId: row.actorId }
      : null;
  } catch {
    return null;
  }
}

export interface OrderPrinceChoiceFact {
  actorId: number;
  day: number;
  activate: boolean;
}
export function readOrderPrinceChoiceFact(
  type: string,
  payload: unknown,
): OrderPrinceChoiceFact | null {
  if (type !== "order_prince_choice_committed") return null;
  try {
    const p = copyEventData(payload);
    if (!p || typeof p !== "object" || Array.isArray(p)) return null;
    const row = p as Record<string, unknown>;
    const positive = (n: unknown) =>
      typeof n === "number" && Number.isSafeInteger(n) && n > 0 && n < Number.MAX_SAFE_INTEGER;
    return Object.keys(row).length === 3 &&
      ["actorId", "day", "activate"].every((k) => Object.hasOwn(row, k)) &&
      positive(row.actorId) &&
      positive(row.day) &&
      typeof row.activate === "boolean"
      ? { actorId: row.actorId as number, day: row.day as number, activate: row.activate }
      : null;
  } catch {
    return null;
  }
}

import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";

export const ORDER_PRINCE_ROLE = "order_prince" as const;
export const ORDER_PRINCE_POLICY = "awa_order_prince_first_ballot_v1" as const;
export interface OrderPrinceChoice {
  day: number;
  activate: boolean;
}
export interface OrderPrinceState {
  policy: typeof ORDER_PRINCE_POLICY;
  history: OrderPrinceChoice[];
}
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((key) => descriptors[key] && "value" in descriptors[key]!)
  );
}
function dayNumber(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function rows(value: unknown): unknown[] | undefined {
  if (types.isProxy(value) || !Array.isArray(value)) return undefined;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return undefined;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return undefined;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return undefined;
    result.push(d.value);
  }
  return result;
}
/** Read the original role state without invoking accessors or proxy traps. */
export function getOrderPrinceState(role: RoleComponent | undefined): OrderPrinceState | undefined {
  if (field(role, "role") !== ORDER_PRINCE_ROLE || field(role, "camp") !== Camp.Good)
    return undefined;
  const state = field(field(role, "privateState"), "orderPrince");
  if (!exact(state, ["policy", "history"]) || field(state, "policy") !== ORDER_PRINCE_POLICY)
    return undefined;
  const history = rows(field(state, "history"));
  if (!history) return undefined;
  let previous = 0;
  let consumed = false;
  for (const row of history) {
    if (!exact(row, ["day", "activate"])) return undefined;
    const day = field(row, "day");
    const activate = field(row, "activate");
    if (!dayNumber(day) || day <= previous || typeof activate !== "boolean" || consumed)
      return undefined;
    previous = day;
    consumed = activate;
  }
  return state as OrderPrinceState;
}
export function createOrderPrinceState(): OrderPrinceState {
  return { policy: ORDER_PRINCE_POLICY, history: [] };
}
export function projectOrderPrinceState(
  role: RoleComponent | undefined,
): OrderPrinceState | undefined {
  const state = getOrderPrinceState(role);
  if (!state) return undefined;
  const history: OrderPrinceChoice[] = [];
  for (const row of rows(field(state, "history"))!) {
    history.push({
      day: field(row, "day") as number,
      activate: field(row, "activate") as boolean,
    });
  }
  return { policy: ORDER_PRINCE_POLICY, history };
}
/** A detached next state; the caller commits it only after current-life checks. */
export function nextOrderPrinceChoice(
  role: RoleComponent | undefined,
  day: number,
  activate: boolean,
): OrderPrinceState | undefined {
  const state = projectOrderPrinceState(role);
  if (!state || !dayNumber(day) || typeof activate !== "boolean") return undefined;
  const last = state.history.at(-1);
  if (last && (last.activate || last.day >= day)) return undefined;
  state.history.push({ day, activate });
  return state;
}

/**
 * Owns Order Prince original identity binding and its pending reveal choice. Inputs are the
 * World and selected target; outputs are currentness checks, reveal state and committed choice
 * evidence. Only the matching pending choice writes; a closed choice prevents stale targets from
 * completing it.
 * The checked orderPrince replacement restores only that slot after the original authority checks, without caching the container.
 */
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { aliveLifeDescriptor, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { World } from "../../../../core/domain/world";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import {
  getOrderPrinceState,
  projectOrderPrinceState,
  nextOrderPrinceChoice,
  ORDER_PRINCE_ROLE,
  type OrderPrinceState,
} from "./state";

interface Authority {
  actorId: number;
  role: RoleComponent;
  privateState: RoleComponent["privateState"];
  state: OrderPrinceState;
  expected: string;
  identity: unknown;
  identityValue: string;
  life: NightLifeScope;
  pendingDay: number | null;
}
const bindings = new WeakMap<World, Authority>();
function own(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function identityValue(value: unknown): string {
  const values = ["id", "seat", "name", "sessionId"].map((key) => own(value, key));
  if (
    !Number.isSafeInteger(values[0]) ||
    !Number.isSafeInteger(values[1]) ||
    typeof values[2] !== "string" ||
    typeof values[3] !== "string"
  )
    throw new Error("order_prince_identity_invalid");
  return JSON.stringify(values);
}
function requireAuthority(world: World): Authority {
  const b = bindings.get(world);
  if (!b) throw new Error("order_prince_board_missing");
  if (
    world.getComponent(b.actorId, COMPONENT.Role) !== b.role ||
    own(b.role, "privateState") !== b.privateState ||
    getOrderPrinceState(b.role) !== b.state ||
    JSON.stringify(projectOrderPrinceState(b.role)) !== b.expected ||
    world.getComponent(b.actorId, COMPONENT.Identity) !== b.identity ||
    identityValue(b.identity) !== b.identityValue
  )
    throw new Error("order_prince_original_state_revoked");
  const life = b.life.life;
  const expected = aliveLifeDescriptor(life);
  const current = Object.getOwnPropertyDescriptor(life, "alive");
  if (
    world.getComponent(b.actorId, COMPONENT.Alive) !== life ||
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable ||
    aliveLifeVersion(life) !== b.life.version + (life.alive ? 0 : 1)
  )
    throw new Error("order_prince_original_life_revoked");
  return b;
}
export function installOrderPrinceBoard(world: World): void {
  if (bindings.has(world)) throw new Error("order_prince_board_already_installed");
  const actors = world
    .entityIds()
    .filter((id) => own(world.getComponent(id, COMPONENT.Role), "role") === ORDER_PRINCE_ROLE);
  if (actors.length !== 1) throw new Error("order_prince_original_roster_invalid");
  const actorId = actors[0]!;
  const role = world.getComponent(actorId, COMPONENT.Role)!;
  const state = getOrderPrinceState(role);
  const life = captureNightLife(world, actorId);
  const identity = world.getComponent(actorId, COMPONENT.Identity);
  if (!state || state.history.length || !life || own(identity, "id") !== actorId)
    throw new Error("order_prince_original_roster_invalid");
  bindings.set(world, {
    actorId,
    role,
    privateState: role.privateState,
    state,
    expected: JSON.stringify(projectOrderPrinceState(role)),
    identity,
    identityValue: identityValue(identity),
    life,
    pendingDay: null,
  });
}
export function openOrderPrinceChoice(world: World, day: number): number | null {
  const b = requireAuthority(world);
  if (b.pendingDay !== null) throw new Error("order_prince_choice_reentrant");
  if (!livingNightLife(world, b.life)) return null;
  if (!nextOrderPrinceChoice(b.role, day, false)) return null;
  b.pendingDay = day;
  return b.actorId;
}
export function orderPrinceChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireAuthority(world);
  return (
    b.actorId === actorId &&
    b.pendingDay === day &&
    livingNightLife(world, b.life) &&
    !!nextOrderPrinceChoice(b.role, day, false)
  );
}
export function assertOrderPrinceCurrent(world: World, actorId: number): void {
  const b = requireAuthority(world);
  if (b.actorId !== actorId || !livingNightLife(world, b.life))
    throw new Error("order_prince_actor_stale");
}
export function commitOrderPrinceChoice(
  world: World,
  actorId: number,
  day: number,
  activate: boolean,
): void {
  if (!orderPrinceChoicePending(world, actorId, day)) throw new Error("order_prince_choice_stale");
  const b = requireAuthority(world);
  const next = nextOrderPrinceChoice(b.role, day, activate);
  if (!next) throw new Error("order_prince_choice_invalid");
  (b.privateState as { orderPrince: OrderPrinceState }).orderPrince = next;
  b.state = next;
  b.expected = JSON.stringify(next);
  b.pendingDay = null;
}
export function closeOrderPrinceChoice(world: World): void {
  const b = bindings.get(world);
  if (b) b.pendingDay = null;
}

export function assertOrderPrinceOriginalCurrent(world: World): void {
  const b = requireAuthority(world);
  assertOrderPrinceCurrent(world, b.actorId);
}

/**
 * Owns pure Ghost Bride wedding, knife capture and tool contracts for wire consumers.
 * Inputs are identifiers and proven inert payload data; outputs are detached
 * shapes or null with original keys, limits, defaults and scalar correlations.
 * freshGhostBrideState creates only a fresh serialized-default object; it never
 * installs a role or owns/spends domain stock, handles or original-life rights.
 * For these inputs the reader never changes rules, resources, phases or action
 * authority. Proxy reflection safety belongs to Node ingress before calling;
 * browser consumers must supply inert data rather than arbitrary JS objects.
 */
import { copyEventData } from "../inert-event-data";

/** One sourced, finite preset. Additional rules require another named policy. */
export const GHOST_BRIDE_POLICY = "awa_melbourne_ghost_bride_v1" as const;
export const GHOST_BRIDE_GOAL = "three_factions_elimination" as const;
export const GHOST_BRIDE_ROLE = "ghost_bride" as const;
export type WeddingStatus = "pending" | "active" | "paired" | "complete" | "failed" | "cancelled";
export interface GhostBrideState {
  policy: typeof GHOST_BRIDE_POLICY;
  remaining: 0 | 1;
  groomId: number | null;
}
export interface WeddingVote {
  actorId: number;
  targetId: number;
}
export interface WeddingSetup {
  policy: typeof GHOST_BRIDE_POLICY;
  status: WeddingStatus;
  actorId: number;
  groomId: number | null;
  witnessId: number | null;
  witnessVotes: WeddingVote[];
}
export interface WeddingPair {
  policy: typeof GHOST_BRIDE_POLICY;
  groupId: string;
  brideId: number;
  groomId: number;
  day: 1;
}
export interface WeddingGroup extends WeddingPair {
  witnessId: number;
}
export type WeddingKnifeOwner = "ordinary_pack" | "pair" | "witness" | "none";
export interface WeddingKnifeCapture {
  policy: typeof GHOST_BRIDE_POLICY;
  groupId: string;
  day: number;
  owner: WeddingKnifeOwner;
  actorIds: number[];
}
export type WeddingTool =
  | { name: "choose_bridegroom"; args: { target_id: number } }
  | { name: "choose_wedding_witness"; args: { target_id: number } }
  | { name: "speak_to_partner"; args: { text: string } }
  | { name: "wedding_kill_vote"; args: { target_id: number | null; abstain: boolean } }
  | { name: "kill_vote"; args: { target_id: number | null; abstain: boolean } };
function record(value: unknown): Record<string, unknown> | null {
  try {
    const p = copyEventData(value);
    return p && typeof p === "object" && !Array.isArray(p) ? (p as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}
function exact(p: Record<string, unknown>, names: readonly string[]): boolean {
  return Object.keys(p).length === names.length && names.every((k) => Object.hasOwn(p, k));
}
function id(value: unknown): value is number {
  return Number.isSafeInteger(value) && (value as number) > 0;
}
function groupId(value: unknown): value is string {
  return typeof value === "string" && /^ghost-bride:1:[1-9][0-9]*$/.test(value);
}
export function freshGhostBrideState(): GhostBrideState {
  return { policy: GHOST_BRIDE_POLICY, remaining: 1, groomId: null };
}
export function readGhostBrideState(value: unknown): GhostBrideState | null {
  const p = record(value);
  return p &&
    exact(p, ["policy", "remaining", "groomId"]) &&
    p.policy === GHOST_BRIDE_POLICY &&
    (p.remaining === 0 || p.remaining === 1) &&
    (p.groomId === null || id(p.groomId)) &&
    (p.remaining === 0 || p.groomId === null)
    ? (p as unknown as GhostBrideState)
    : null;
}
export function readWeddingPair(value: unknown): WeddingPair | null {
  const p = record(value);
  return p &&
    exact(p, ["policy", "groupId", "brideId", "groomId", "day"]) &&
    p.policy === GHOST_BRIDE_POLICY &&
    groupId(p.groupId) &&
    p.day === 1 &&
    id(p.brideId) &&
    id(p.groomId) &&
    p.brideId !== p.groomId &&
    p.groupId === `ghost-bride:1:${p.brideId}`
    ? (p as unknown as WeddingPair)
    : null;
}
export function readWeddingGroup(value: unknown): WeddingGroup | null {
  const p = record(value);
  if (!p || !exact(p, ["policy", "groupId", "brideId", "groomId", "day", "witnessId"])) return null;
  const { witnessId, ...pair } = p;
  return readWeddingPair(pair) &&
    id(witnessId) &&
    witnessId !== p.brideId &&
    witnessId !== p.groomId
    ? (p as unknown as WeddingGroup)
    : null;
}
export function readWeddingSetup(value: unknown): WeddingSetup | null {
  const p = record(value);
  if (
    !p ||
    !exact(p, ["policy", "status", "actorId", "groomId", "witnessId", "witnessVotes"]) ||
    p.policy !== GHOST_BRIDE_POLICY ||
    !id(p.actorId) ||
    !["pending", "active", "paired", "complete", "failed", "cancelled"].includes(
      p.status as string,
    ) ||
    (p.groomId !== null && (!id(p.groomId) || p.groomId === p.actorId)) ||
    (p.witnessId !== null &&
      (!id(p.witnessId) || p.witnessId === p.actorId || p.witnessId === p.groomId)) ||
    !Array.isArray(p.witnessVotes) ||
    p.witnessVotes.length > 2
  )
    return null;
  const votes = p.witnessVotes as unknown[];
  if (
    !votes.every((v, i) => {
      const a = record(v);
      return (
        a &&
        exact(a, ["actorId", "targetId"]) &&
        a.actorId === (i === 0 ? p.actorId : p.groomId) &&
        id(a.targetId) &&
        a.targetId !== p.actorId &&
        a.targetId !== p.groomId
      );
    })
  )
    return null;
  if (p.status === "pending" || p.status === "active") {
    if (p.groomId !== null || p.witnessId !== null || votes.length !== 0) return null;
  } else if (p.status === "complete") {
    if (
      p.groomId === null ||
      p.witnessId === null ||
      votes.length !== 2 ||
      !(votes as WeddingVote[]).every((v) => v.targetId === p.witnessId)
    )
      return null;
  } else {
    if (
      p.witnessId !== null ||
      (p.groomId === null && votes.length > 0) ||
      (p.status === "paired" && (p.groomId === null || votes.length > 1)) ||
      (votes.length === 2 &&
        (votes[0] as WeddingVote).targetId === (votes[1] as WeddingVote).targetId)
    )
      return null;
  }
  return p as unknown as WeddingSetup;
}
export function readWeddingKnifeCapture(value: unknown): WeddingKnifeCapture | null {
  const p = record(value);
  if (
    !p ||
    !exact(p, ["policy", "groupId", "day", "owner", "actorIds"]) ||
    p.policy !== GHOST_BRIDE_POLICY ||
    !groupId(p.groupId) ||
    !id(p.day) ||
    !["ordinary_pack", "pair", "witness", "none"].includes(p.owner as string) ||
    !Array.isArray(p.actorIds) ||
    !p.actorIds.every(id) ||
    new Set(p.actorIds).size !== p.actorIds.length
  )
    return null;
  const n = p.actorIds.length;
  return (
    p.owner === "none"
      ? n === 0
      : p.owner === "pair"
        ? n === 2
        : p.owner === "witness"
          ? n === 1
          : n >= 1 && n <= 3
  )
    ? (p as unknown as WeddingKnifeCapture)
    : null;
}
export function readWeddingTool(value: unknown): WeddingTool | null {
  const p = record(value),
    a = record(p?.args);
  if (!p || !exact(p, ["name", "args"]) || !a) return null;
  if (p.name === "choose_bridegroom" || p.name === "choose_wedding_witness")
    return exact(a, ["target_id"]) && id(a.target_id) ? (p as unknown as WeddingTool) : null;
  if (p.name === "speak_to_partner")
    return exact(a, ["text"]) && typeof a.text === "string" ? (p as unknown as WeddingTool) : null;
  if (p.name === "wedding_kill_vote" || p.name === "kill_vote")
    return exact(a, ["target_id", "abstain"]) &&
      ((a.abstain === true && a.target_id === null) || (a.abstain === false && id(a.target_id)))
      ? (p as unknown as WeddingTool)
      : null;
  return null;
}

export const GHOST_BRIDE_EVENT_TYPES = [
  "ghost_bride_pair_chosen",
  "ghost_bride_witness_vote",
  "ghost_bride_group_chosen",
  "ghost_bride_partner_chat",
  "ghost_bride_knife_captured",
  "ghost_bride_knife_vote",
  "ghost_bride_knife_resolved",
  "ghost_bride_partner_death",
] as const;
export function readGhostBrideEventFact(
  type: string,
  value: unknown,
): Record<string, unknown> | null {
  const p = record(value);
  if (!p || p.policy !== GHOST_BRIDE_POLICY || !groupId(p.groupId)) return null;
  if (type === "ghost_bride_pair_chosen") return readWeddingPair(p) ? p : null;
  if (type === "ghost_bride_group_chosen") return readWeddingGroup(p) ? p : null;
  if (type === "ghost_bride_knife_captured") return readWeddingKnifeCapture(p) ? p : null;
  if (type === "ghost_bride_witness_vote")
    return exact(p, ["policy", "groupId", "day", "actorId", "targetId", "voteIndex"]) &&
      p.day === 1 &&
      id(p.actorId) &&
      id(p.targetId) &&
      p.actorId !== p.targetId &&
      (p.voteIndex === 1 || p.voteIndex === 2)
      ? p
      : null;
  if (type === "ghost_bride_partner_chat")
    return exact(p, ["policy", "groupId", "day", "actorId", "recipientId", "text"]) &&
      id(p.day) &&
      id(p.actorId) &&
      id(p.recipientId) &&
      p.actorId !== p.recipientId &&
      typeof p.text === "string"
      ? p
      : null;
  if (type === "ghost_bride_knife_vote")
    return exact(p, ["policy", "groupId", "day", "owner", "actorId", "targetId", "abstain"]) &&
      id(p.day) &&
      id(p.actorId) &&
      ["ordinary_pack", "pair", "witness"].includes(p.owner as string) &&
      ((p.targetId === null && p.abstain === true) || (id(p.targetId) && p.abstain === false))
      ? p
      : null;
  if (type === "ghost_bride_knife_resolved") {
    const { targetId, ...capture } = p;
    return readWeddingKnifeCapture(capture) && (targetId === null || id(targetId)) ? p : null;
  }
  if (type === "ghost_bride_partner_death")
    return exact(p, ["policy", "groupId", "day", "actorId", "targetId", "phase"]) &&
      id(p.day) &&
      id(p.actorId) &&
      id(p.targetId) &&
      p.actorId !== p.targetId &&
      ["night", "day", "voting"].includes(p.phase as string)
      ? p
      : null;
  return null;
}

/**
 * 负责鬼新娘婚礼回合、原参与者快照与有序提交，拥有婚礼选择和绑定别名的写权。
 * 输入保留原 World 及封存请求；输出为原校验后已接受的选择、消息与结算记录。
 * 不变量：提交必须匹配原参与者和绑定回合，别名不能替代本地校验。取消、关闭或失败
 * 均保持原结算及部分写入顺序，不修复被替换的库存。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import { types } from "node:util";
import { GHOST_BRIDE_POLICY, GHOST_BRIDE_ROLE, freshGhostBrideState, readGhostBrideState, type GhostBrideState, type WeddingPair, type WeddingGroup, type WeddingSetup, type WeddingKnifeCapture, type WeddingTool, readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import {
  bindRequestDeliveryGuard,
  settleRequestDelivery,
  DeathCause,
  type DeathSources,
  COMPONENT,
  Camp,
  Role,
  Phase,
  createVictoryComponent,
  type World,
  type RoleComponent,
  type CampComponent,
  type VictoryComponent,
} from "../../../../core/domain";
import {
  aliveLifeVersion,
  aliveLifeDescriptor,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import { assertGhostBridePreset } from "./preset";

/** 只读 own data；拒绝或审计期间不执行被替换的 getter。 */
function data(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
